SEO_FILENAMES=tuple('seo_'+slug+'.html' for slug,*_ in SEO_HUBS)
HUB_KEYWORDS={
    'zero-rank-hidden-class':('нулев','ранг'), 'lightning-science':('рельсотрон','молни'),
    'dungeons-raids':('подземел','рейд'), 'cultivation-growth':('садовниц','культивац'),
    'holy-light-magic':('свят','свет'), 'taming-evolution':('прируч','укрот','эволюц'),
    'companions-monsters':('прируч','укрот'), 'unusual-professions':('пивовар','садовниц','самозанят'),
    'crafting-technology':('пивовар','рельсотрон'), 'smart-protagonists':('рельсотрон','навык'),
}


def select_books(books,genres,limit=3,*,slug=''):
    """Prefer exact genre shelves; always disclose each card's actual genre."""
    terms=HUB_KEYWORDS.get(slug,())
    return sorted(books,key=lambda b:(not any(term in b['series']['title'].casefold() for term in terms),
        b['series'].get('genre_slug') not in genres,
        genres.index(b['series'].get('genre_slug')) if b['series'].get('genre_slug') in genres else 99,
        b['series']['id']))[:limit]
